ss_bus_slice.vhdl:
library ieee;
use ieee.std_logic_1164.all;
entity ss_bus_slice is
  generic (IN_WIDTH:positive range 1 to 64:=16;
    OUT_WIDTH:positive range 1 to IN_WIDTH:=8;
    LSB:natural range 0 to IN_WIDTH-OUT_WIDTH:=0);
  port (d:in std_logic_vector(IN_WIDTH-1 downto 0);
    y:out std_logic_vector(OUT_WIDTH-1 downto 0));
end entity;
architecture rtl of ss_bus_slice is begin
  y <= d(LSB+OUT_WIDTH-1 downto LSB);
end architecture;

ss_bus_concat.vhdl:
library ieee;
use ieee.std_logic_1164.all;
entity ss_bus_concat is
  generic (A_WIDTH:positive range 1 to 63:=8; B_WIDTH:positive range 1 to 64-A_WIDTH:=8);
  port (a:in std_logic_vector(A_WIDTH-1 downto 0);
    b:in std_logic_vector(B_WIDTH-1 downto 0);
    y:out std_logic_vector(A_WIDTH+B_WIDTH-1 downto 0));
end entity;
architecture rtl of ss_bus_concat is begin
  y <= a & b;
end architecture;

ss_bus_reverse.vhdl:
library ieee;
use ieee.std_logic_1164.all;
entity ss_bus_reverse is
  generic (WIDTH:positive range 1 to 64:=8);
  port (d:in std_logic_vector(WIDTH-1 downto 0);
    y:out std_logic_vector(WIDTH-1 downto 0));
end entity;
architecture rtl of ss_bus_reverse is begin
  bits:for i in 0 to WIDTH-1 generate y(i)<=d(WIDTH-1-i); end generate;
end architecture;

ss_bus_zero_extend.vhdl:
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
entity ss_bus_zero_extend is
  generic (IN_WIDTH:positive range 1 to 64:=8; OUT_WIDTH:positive range IN_WIDTH to 64:=16);
  port (d:in std_logic_vector(IN_WIDTH-1 downto 0);
    y:out std_logic_vector(OUT_WIDTH-1 downto 0));
end entity;
architecture rtl of ss_bus_zero_extend is begin
  y <= std_logic_vector(resize(unsigned(d),OUT_WIDTH));
end architecture;

